package com.yin.utils.bese64;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Base64;

/**
 * @author yin
 * @date 2024-11-15
 * @Description
 */
public class Base64Utils {
    public static String s="";

    public static void main(String[] args) {
        String s="";

        convertBase64ToImage(s,"E:\\文件信息保存\\2024-11-15\\1.jpg");
    }

    /**
     * 转换base64到图片
     * @param base64Str base64编码
     * @param path 图片地址
     */
    public static void convertBase64ToImage(String base64Str,String path){
        byte[] imageBytes = Base64.getDecoder().decode(base64Str);
        try(OutputStream out = Files.newOutputStream(Paths.get(path))){
            out.write(imageBytes);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static byte[] base64ToByte(String base64Str){
        return Base64.getDecoder().decode(base64Str);
    }



}
